const config = {
    "previewFeatures": [],
    "clientVersion": "7.8.0",
    "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
    "activeProvider": "sqlite",
    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Get a free hosted Postgres database in seconds: `npx create-db`\n\ngenerator client {\n  provider     = \"prisma-client\"\n  output       = \"../src/generated/prisma\"\n  moduleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\n// ─────────────────────────────────────────\n// AUTH (Better Auth génère ces tables)\n// ─────────────────────────────────────────\n\nmodel User {\n  id            String   @id @default(cuid())\n  name          String\n  email         String   @unique\n  emailVerified Boolean  @default(false)\n  image         String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  role Role @default(ELEVE)\n\n  sessions Session[]\n  accounts Account[]\n\n  // Relations métier\n  eleve      Eleve?\n  professeur Professeur?\n  parent     Parent?\n  ecole      Ecole?\n\n  @@map(\"user\")\n}\n\nmodel Session {\n  id        String   @id @default(cuid())\n  userId    String\n  token     String   @unique\n  expiresAt DateTime\n  ipAddress String?\n  userAgent String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"session\")\n}\n\nmodel Account {\n  id           String    @id @default(cuid())\n  userId       String\n  accountId    String\n  providerId   String\n  accessToken  String?\n  refreshToken String?\n  expiresAt    DateTime?\n  password     String?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  idToken               String?\n  accessTokenExpiresAt  DateTime?\n  refreshTokenExpiresAt DateTime?\n  scope                 String?\n\n  @@index([userId])\n  @@map(\"account\")\n}\n\nmodel Verification {\n  id         String   @id @default(cuid())\n  identifier String\n  value      String\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@index([identifier])\n  @@map(\"verification\")\n}\n\n// ─────────────────────────────────────────\n// RÔLES\n// ─────────────────────────────────────────\n\nenum Role {\n  ADMIN\n  PROFESSEUR\n  ELEVE\n  PARENT\n}\n\n// ─────────────────────────────────────────\n// MÉTIER\n// ─────────────────────────────────────────\n\nmodel Ecole {\n  id             String          @id @default(cuid())\n  nom            String          @unique\n  adresse        String?\n  telephone      String?\n  email          String?         @unique\n  siteWeb        String?\n  logo           String? // URL\n  directeur      String?\n  ville          String?\n  pays           String          @default(\"Sénégal\")\n  codePostal     String?\n  description    String?\n  userId         String          @unique\n  user           User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n  professeurs    Professeur[]\n  classes        Classe[]\n  frais          FraisScolaire[]\n  communications Communication[]\n\n  @@map(\"ecole\")\n}\n\nmodel Eleve {\n  id            String    @id @default(cuid())\n  userId        String    @unique\n  matricule     String    @unique\n  dateNaissance DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  user     User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  classe   Classe? @relation(fields: [classeId], references: [id])\n  classeId String?\n\n  notes   Note[]\n  parents ParentEleve[]\n  frais   FraisScolaire[]\n\n  @@map(\"eleve\")\n}\n\nmodel Parent {\n  id        String   @id @default(cuid())\n  userId    String   @unique\n  telephone String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user    User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  enfants ParentEleve[]\n\n  @@map(\"parent\")\n}\n\n// Table de jonction Parent <-> Eleve (un parent peut avoir plusieurs enfants)\n\nmodel ParentEleve {\n  parentId String\n  eleveId  String\n\n  parent Parent @relation(fields: [parentId], references: [id], onDelete: Cascade)\n  eleve  Eleve  @relation(fields: [eleveId], references: [id], onDelete: Cascade)\n\n  @@id([parentId, eleveId])\n  @@map(\"parent_eleve\")\n}\n\nmodel Professeur {\n  id         String   @id @default(cuid())\n  userId     String   @unique\n  ecoleId    String\n  specialite String?\n  telephone  String?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  user         User                @relation(fields: [userId], references: [id], onDelete: Cascade)\n  ecole        Ecole               @relation(fields: [ecoleId], references: [id], onDelete: Cascade)\n  matieres     ProfesseurMatiere[]\n  classes      ProfesseurClasse[]\n  evaluations  Evaluation[]\n  classe       Classe[]\n  emploisTemps EmploiTemps[]\n\n  @@map(\"professeur\")\n}\n\nmodel Classe {\n  id         String      @id @default(cuid())\n  ecoleId    String\n  profId     String?\n  nom        String // ex: \"6ème A\", \"Terminale S\"\n  niveau     String // ex: \"6ème\", \"Terminale\"\n  annee      String // ex: \"2024-2025\"\n  createdAt  DateTime    @default(now())\n  updatedAt  DateTime    @updatedAt\n  ecole      Ecole       @relation(fields: [ecoleId], references: [id], onDelete: Cascade)\n  professeur Professeur? @relation(fields: [profId], references: [id], onDelete: SetNull)\n\n  eleves       Eleve[]\n  matieres     Matiere[]\n  professeurs  ProfesseurClasse[]\n  emploisTemps EmploiTemps[]\n\n  @@map(\"classe\")\n}\n\nmodel Matiere {\n  id          String   @id @default(cuid())\n  nom         String // ex: \"Mathématiques\"\n  coefficient Int      @default(1)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  classeId String\n  classe   Classe @relation(fields: [classeId], references: [id], onDelete: Cascade)\n\n  professeurs  ProfesseurMatiere[]\n  evaluations  Evaluation[]\n  emploisTemps EmploiTemps[]\n\n  @@map(\"matiere\")\n}\n\n// Table de jonction Professeur <-> Matiere\n\nmodel ProfesseurMatiere {\n  professeurId String\n  matiereId    String\n\n  professeur Professeur @relation(fields: [professeurId], references: [id], onDelete: Cascade)\n  matiere    Matiere    @relation(fields: [matiereId], references: [id], onDelete: Cascade)\n\n  @@id([professeurId, matiereId])\n  @@map(\"professeur_matiere\")\n}\n\n// Table de jonction Professeur <-> Classe\n\nmodel ProfesseurClasse {\n  professeurId String\n  classeId     String\n\n  professeur Professeur @relation(fields: [professeurId], references: [id], onDelete: Cascade)\n  classe     Classe     @relation(fields: [classeId], references: [id], onDelete: Cascade)\n\n  @@id([professeurId, classeId])\n  @@map(\"professeur_classe\")\n}\n\nmodel EmploiTemps {\n  id         String   @id @default(cuid())\n  jour       Jour // Lundi, Mardi, Mercredi, Jeudi, Vendredi, Samedi\n  heureDebut String // ex: \"07:30\"\n  heureFin   String // ex: \"08:30\"\n  salle      String?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  classeId     String\n  classe       Classe      @relation(fields: [classeId], references: [id], onDelete: Cascade)\n  matiereId    String\n  matiere      Matiere     @relation(fields: [matiereId], references: [id], onDelete: Cascade)\n  professeurId String?\n  professeur   Professeur? @relation(fields: [professeurId], references: [id])\n\n  @@map(\"emploi_temps\")\n}\n\nenum Jour {\n  LUNDI\n  MARDI\n  MERCREDI\n  JEUDI\n  VENDREDI\n  SAMEDI\n}\n\nmodel Evaluation {\n  id        String   @id @default(cuid())\n  titre     String // ex: \"Devoir 1\", \"Examen trimestriel\"\n  type      EvalType\n  date      DateTime\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  matiereId String\n  matiere   Matiere @relation(fields: [matiereId], references: [id], onDelete: Cascade)\n\n  professeurId String\n  professeur   Professeur @relation(fields: [professeurId], references: [id])\n\n  semestre Int @default(1)\n\n  notes Note[]\n\n  @@map(\"evaluation\")\n}\n\nenum EvalType {\n  DEVOIR\n  INTERROGATION\n  EXAMEN\n  RATTRAPAGE\n}\n\nmodel Note {\n  id           String   @id @default(cuid())\n  valeur       Float // note sur 20\n  appreciation String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  eleveId String\n  eleve   Eleve  @relation(fields: [eleveId], references: [id], onDelete: Cascade)\n\n  evaluationId String\n  evaluation   Evaluation @relation(fields: [evaluationId], references: [id], onDelete: Cascade)\n\n  // un élève a une seule note par évaluation\n  @@unique([eleveId, evaluationId])\n  @@map(\"note\")\n}\n\n// ─────────────────────────────────────────\n// FRAIS SCOLAIRES & PAIEMENTS\n// ─────────────────────────────────────────\n\nmodel FraisScolaire {\n  id          String   @id @default(cuid())\n  eleveId     String\n  libelle     String // ex: \"Inscription 2024-25\", \"Mensualité Octobre\"\n  montant     Float // Montant total dû\n  montantPaye Float    @default(0)\n  echeance    DateTime // Date d'échéance\n  statut      String   @default(\"impayé\") // \"impayé\", \"partiel\", \"payé\", \"en_retard\"\n  ecoleId     String\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  eleve     Eleve      @relation(fields: [eleveId], references: [id], onDelete: Cascade)\n  ecole     Ecole      @relation(fields: [ecoleId], references: [id], onDelete: Cascade)\n  paiements Paiement[]\n\n  @@map(\"frais_scolaire\")\n}\n\nmodel Communication {\n  id        String   @id @default(cuid())\n  ecoleId   String\n  title     String\n  content   String\n  target    String   @default(\"all\") // \"all\", \"eleves\", \"professeurs\"\n  createdAt DateTime @default(now())\n\n  ecole Ecole @relation(fields: [ecoleId], references: [id], onDelete: Cascade)\n\n  @@map(\"communication\")\n}\n\nmodel Paiement {\n  id           String   @id @default(cuid())\n  fraisId      String\n  montant      Float\n  methode      String // \"especes\", \"virement\", \"mobile_money\", \"cheque\"\n  reference    String?\n  datePaiement DateTime @default(now())\n  createdAt    DateTime @default(now())\n\n  frais FraisScolaire @relation(fields: [fraisId], references: [id], onDelete: Cascade)\n\n  @@map(\"paiement\")\n}\n",
    "runtimeDataModel": {
        "models": {},
        "enums": {},
        "types": {}
    },
    "parameterizationSchema": {
        "strings": [],
        "graph": ""
    }
};
